SELECT DISTINCT p.name FROM people AS p JOIN stars AS s ON p.id = s.person_id WHERE s.movie_id IN (SELECT DISTINCT m.id FROM people AS p JOIN stars AS s ON p.id = s.person_id JOIN movies AS m ON s.movie_id = m.id WHERE p.name = 'Kevin Bacon' AND p.birth = '1958') AND NOT (p.name = 'Kevin Bacon' AND p.birth = 1958);
